// Simulación en Node de localStorage y fetch del navegador: no existen en Node,
// así que se modela `localStorage` con una clase mínima y `fetch` con una
// función asíncrona que devuelve la misma forma que un `Response` real.
class FakeStorage {
  constructor() { this.data = {}; }
  setItem(key, value) { this.data[key] = String(value); }
  getItem(key) { return key in this.data ? this.data[key] : null; }
  removeItem(key) { delete this.data[key]; }
}
const localStorage = new FakeStorage();

localStorage.setItem('theme', 'dark');
console.log(localStorage.getItem('theme'));
console.log(localStorage.getItem('missing'));

async function fakeFetch(url) {
  return { ok: true, status: 200, json: async () => ({ id: 1, name: 'Ada' }) };
}

const response = await fakeFetch('/api/users/1');
const user = await response.json();
console.log(response.status, user.name);
